// Normaliza el input: HTTP directo o llamada desde WF-C (Slack Events)
const raw = $input.first().json || {};
const body = raw.body?.message || raw.body?.text || raw.body?.query || raw.body?.pregunta
  ? raw.body
  : (raw.body?.body || raw.body || raw);

const message = body.message || body.text || body.query || body.pregunta || body.input || '';
const session_id = body.session_id || body.user_id || raw.headers?.['x-session-id'] || 'default';

// Campos Slack (solo presentes si viene de WF-C)
const slack_channel_id = body.slack_channel_id || null;
const slack_thread_ts  = body.slack_thread_ts  || null;
const slack_msg_ts     = body.slack_msg_ts     || null;
const slack_user       = body.slack_user       || null;

// Detectar si la pregunta vino DENTRO de un hilo existente
// (slack_thread_ts presente y distinto del mensaje actual = es un reply)
const is_thread_reply = !!slack_thread_ts && slack_thread_ts !== slack_msg_ts;

if (!message || !String(message).trim()) {
  throw new Error('Falta el campo message en el body. Recibido: ' + JSON.stringify(raw).slice(0, 500));
}
return [{ json: { message: String(message).trim(), session_id, slack_channel_id, slack_thread_ts, slack_msg_ts, slack_user, is_thread_reply } }];

const agentOutput = $('Agente OPEX (Claude)').first().json.output || 'Sin respuesta del agente.';
const input = $('Normalizar input').first().json;
const channelId  = input.slack_channel_id;
const threadTs   = input.slack_thread_ts;
const msgTs      = input.slack_msg_ts;
const slackUser  = input.slack_user || '';

// Para responder SIEMPRE en hilo:
// - si la pregunta ya estaba en un hilo → respondemos en ese hilo (thread_ts del padre)
// - si fue mensaje top-level → iniciamos hilo usando ts del mensaje original
const replyThreadTs = threadTs || msgTs;

// memory_id para botones de feedback
let memory_id = null;
try { memory_id = $('Guardar en memoria').first().json.id; } catch(e) {}

// Convertir markdown → Slack mrkdwn
let text = agentOutput
  .replace(/\*\*(.+?)\*\*/g, '*$1*')
  .replace(/#{1,3}\s+(.+)/g, '*$1*')
  .replace(/^---+$/gm, '')
  .trim();
if (text.length > 2900) text = text.slice(0, 2897) + '...';

const blocks = [
  {
    type: 'section',
    text: { type: 'mrkdwn', text: `🔮 *Oráculo del OPEX*\n\n${text}` }
  }
];

// Botones de feedback solo si viene de Slack y tenemos memory_id
if (memory_id && channelId) {
  blocks.push({
    type: 'actions',
    elements: [
      {
        type: 'button',
        text: { type: 'plain_text', text: '👍 Útil' },
        value: `good_${memory_id}`,
        action_id: 'feedback_good'
      },
      {
        type: 'button',
        text: { type: 'plain_text', text: '👎 Mejorar' },
        value: `bad_${memory_id}`,
        action_id: 'feedback_bad'
      }
    ]
  });
}

blocks.push({
  type: 'context',
  elements: [{ type: 'mrkdwn', text: `Powered by Claude Sonnet${slackUser ? ' · <@' + slackUser + '>' : ''}` }]
});

const payload = {
  channel: channelId,
  text: `🔮 *Oráculo del OPEX*\n\n${text}`,
  blocks
};
if (replyThreadTs) payload.thread_ts = replyThreadTs;

return [{ json: { payload } }];

const input = $('Normalizar input').first().json;
const message = input.message;

let history = [], prefs = { response_style: 'balanced', notes: '' };

try {
  const ctx = $('Cargar contexto usuario').first().json;
  if (ctx.history && Array.isArray(ctx.history)) history = ctx.history;
  if (ctx.prefs && typeof ctx.prefs === 'object') prefs = { ...prefs, ...ctx.prefs };
} catch(e) {}

// Mensaje padre del hilo (si la pregunta vino dentro de un hilo existente)
let parentText = '';
try {
  const parentRes = $('Fetch hilo padre').first().json;
  if (input.is_thread_reply && parentRes && parentRes.ok && Array.isArray(parentRes.messages) && parentRes.messages[0]) {
    const t = (parentRes.messages[0].text || '').replace(/<@[A-Z0-9]+>/gi, '').trim();
    if (t) parentText = t;
  }
} catch (e) {}

// Fecha actual en zona horaria Colombia
const now = new Date();
const bogotaDate = new Intl.DateTimeFormat('es-CO', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'America/Bogota'
}).format(now);
const isoDate = new Intl.DateTimeFormat('en-CA', {
  year: 'numeric', month: '2-digit', day: '2-digit',
  timeZone: 'America/Bogota'
}).format(now);
const yyyy = isoDate.slice(0, 4);
const mm = isoDate.slice(5, 7);
const prevMonth = new Date(parseInt(yyyy), parseInt(mm) - 1 - 1, 1);
const prevMonthLabel = prevMonth.toLocaleDateString('es-CO', { year: 'numeric', month: 'long', timeZone: 'America/Bogota' });

let contextBlock = `[FECHA ACTUAL]\nHoy es ${bogotaDate} (${isoDate}, zona horaria America/Bogota).\n\"Hoy\" = ${isoDate}. \"Este mes\" = ${yyyy}-${mm}. \"El mes pasado\" = ${prevMonthLabel}.\nUsa SIEMPRE estas referencias para resolver fechas relativas. Ignora cualquier conocimiento previo sobre la fecha.\n[/FECHA ACTUAL]\n\n`;

if (parentText) {
  contextBlock += `[MENSAJE PADRE DEL HILO]\nEl usuario te tagueó dentro de un hilo. El mensaje original que abrió el hilo es:\n\"${parentText.slice(0, 1500)}\"\nUsa este mensaje original como contexto principal a menos que la pregunta actual indique otra cosa.\n[/MENSAJE PADRE]\n\n`;
}

if (history.length > 0) {
  const lines = history.map(h =>
    `• \"${h.question.slice(0, 100)}\" ${h.rating || ''}\n  → ${h.answer.slice(0, 250)}...`
  ).join('\n');
  contextBlock += `[HISTORIAL RECIENTE]\n${lines}\n[/HISTORIAL]\n\n`;
}

const style = prefs.response_style || 'balanced';
const notes = prefs.notes || '';
contextBlock += `[PREFERENCIAS] Estilo: ${style}.${notes ? ' ' + notes : ''} [/PREFERENCIAS]\n\n`;

const enrichedMessage = contextBlock + 'Pregunta actual: ' + message;

return [{ json: { ...input, message: enrichedMessage } }];
